const CORE=["./", "index.html", "data.js", "game.js", "manifest.webmanifest"];
const key=f=>f+'?v='+FILES[f];
const rel=u=>{try{const p=new URL(u).pathname,s=new URL(self.registration.scope).pathname;return p.startsWith(s)?decodeURIComponent(p.slice(s.length)):'';}catch(_){return '';}};
self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(CACHE).then(async c=>{
 await Promise.allSettled(CORE.map(f=>c.add(new Request(f,{cache:'reload'}))));
 const need=[];
 await Promise.allSettled(Object.keys(FILES).map(async f=>{const k=key(f);if(await c.match(k))return;const r=await caches.match(k);if(r)await c.put(k,r);else need.push(f);}));
 let i=0;const w=async()=>{while(i<need.length){const f=need[i++];try{if(await c.match(key(f)))continue;const r=await fetch(f,{cache:'reload'});if(r.ok)await c.put(key(f),r);}catch(_){}}};
 Promise.all([w(),w(),w(),w()]);
}));});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()).then(()=>self.clients.matchAll({type:'window'})).then(cs=>cs.forEach(c=>{try{c.postMessage({type:'sw-new'});}catch(_){}})));});
const isCore=u=>{const p=new URL(u).pathname;return p.endsWith('/')||/\/(index\.html|game\.js|data\.js|manifest\.webmanifest|sw\.js)$/.test(p);};
self.addEventListener('fetch',e=>{const q=e.request;if(q.method!=='GET')return;
 if(q.mode==='navigate'||isCore(q.url)){e.respondWith(fetch(q,{cache:'no-cache'}).then(r=>{if(r.ok){const k=r.clone();caches.open(CACHE).then(c=>c.put(q,k));}return r;}).catch(()=>caches.match(q,{ignoreSearch:true}).then(r=>r||caches.match('index.html'))));return;}
 e.respondWith(caches.match(q,{ignoreSearch:true}).then(r=>r||fetch(q).then(n=>{if(n.ok){const k=n.clone(),f=rel(q.url);caches.open(CACHE).then(c=>c.put(FILES[f]?key(f):q,k));}return n;})));});
